                @Override
                public void onCompleted() {
                    Timber.d("onCompleted");
                    unsubscribe();
                    stopForeground(true);
                    stopSelf();

                }

                @Override
                public void onError(Throwable e) {
                    Timber.e("onError");
                }

                @Override
