            mPlusClient.disconnect();
            mPlusClient.connect();

            // Hide the sign out buttons, show the sign in button.
            findViewById(R.id.sign_in_button).setVisibility(View.VISIBLE);
            findViewById(R.id.sign_out_button).setVisibility(View.GONE);

